head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.basYYYY = "2017";
scwin.periodYYYY;
scwin.periodTmCd;
scwin.procJob;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top_1);
        await scwin.period();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41401.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function() {
    try {
        self.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41401.btn_Close_onclick" });
    }
};

/**
