 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Mbr_List_1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Mbr_List_1);
        // alert(getMessageParam("MSG-0002", ""));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41401.dts_Mbr_List_1_OnLoadError" });
    }
};

