/**
 * @method
 * @name dts_Mbr_List_1_OnLoadCompleted
 * @description dts_Mbr_List_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mbr_List_1_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount <= 0) {
            dts_Mbr_List_1.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41401.dts_Mbr_List_1_OnLoadCompleted" });
    }
};

