/**
 * @method
 * @name cmd_Period_onselchange
 * @description cmd_Period onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmd_Period_onselchange = function() {
    try {
        scwin.periodYYYY = dts_Period.getCellData(dts_Period.getRowPosition(), "YYYY");
        scwin.periodTmCd = dts_Period.getCellData(dts_Period.getRowPosition(), "VALU_TM_TP_CD");
        if (scwin.periodYYYY >= scwin.basYYYY) {
            edt_SDate_all.setValue((scwin.periodYYYY - 1) + "0101");
            edt_EDate_all.setValue((scwin.periodYYYY - 1) + "1231");
        } else {
            edt_SDate_all.setValue(dts_Period.getCellData(dts_Period.getRowPosition(), "STRT_DD"));
            edt_EDate_all.setValue(dts_Period.getCellData(dts_Period.getRowPosition(), "END_DD"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41401.cmd_Period_onselchange" });
    }
};

/**
 * @method
 * @name dts_Period_OnLoadCompleted
 * @description dts_Period 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Period_OnLoadCompleted = function(rowcount) {
    try {
        scwin.periodYYYY = dts_Period.getCellData(dts_Period.getRowPosition(), "YYYY");
        scwin.periodTmCd = dts_Period.getCellData(dts_Period.getRowPosition(), "VALU_TM_TP_CD");
        if (scwin.periodYYYY >= scwin.basYYYY) {
            edt_SDate_all.setValue((scwin.periodYYYY - 1) + "0101");
            edt_EDate_all.setValue((scwin.periodYYYY - 1) + "1231");
        } else {
            edt_SDate_all.setValue(dts_Period.getCellData(dts_Period.getRowPosition(), "STRT_DD"));
            edt_EDate_all.setValue(dts_Period.getCellData(dts_Period.getRowPosition(), "END_DD"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41401.dts_Period_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_search_all_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_all_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41401.btn_search_all_onclick" });
    }
};

/**
 * @method
 * @name image_2_onclick
 * @description image_2 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.image_2_onclick = async function() {
    try {
        await scwin.emplog();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41401.image_2_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41401.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41401.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Excel_1_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_1_onclick = function() {
    try {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF41401.xml", SCREN_PROCS_TP_CD_07);
        const today = $c.ut.cGetToday("yyyymmddhhmmss");
        // 파일형식 today_화면명.xls
        const xls_path = $c.session.getExcelDownPath() + today + "_대표주관회사평가확인목록_STF41401.xls";
        $c.data.saveExcel(grd_Mbr_List_1, "증권회사별 실적 종합", false, false, false, xls_path);
        $c.data.downloadGridViewExcel(grd_Mbr_List_2, {fileName: "신규상장 기업별 상장이후 주가 추이", sheetName: xls_path, type: "40"});
        $c.data.downloadGridViewExcel(grd_Mbr_List_3, {fileName: "신규상장 기업별 상장이후 당기순이익 추이", sheetName: xls_path, type: "40"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41401.btn_Excel_1_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name period
 * @description 대표주관사 평가기간 변경 기준일
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.period = async function() {
    // 기간조회
    const sbmOptions = {
        id : "sbm_dts_Period",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Period=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_mktpartcList",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_mktpartcList=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let mktpartcList;
    if (cmd_mktpartcList.BindColVal === "") mktpartcList = "A";

    else mktpartcList = cmd_mktpartcList.BindColVal;
    const sbmOptions = {
        id : "sbm_dts_Mbr_List_1",
        action : "/RepMajagnt.do",
        ref : "",
        target : "dts_Mbr_List_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_Mbr_List_2",
        action : "/RepMajagnt.do",
        ref : "",
        target : "dts_Mbr_List_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_Mbr_List_3",
        action : "/RepMajagnt.do",
        ref : "",
        target : "dts_Mbr_List_3=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자확인 조회
    const sbmOptions4 = {
        id : "sbm_dts_EmpNo",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_EmpNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name emplog
 * @description 담당자 확인
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.emplog = async function() {
    if (dts_EmpNo.getRowCount() > 0) {
        await $c.win.alert("이미 담당자 확인을 하셨습니다.");
    } else {
        const res = window.confirm("담당자 확인을 하시겠습니까?");
        if (res) {
            scwin.procJob = "담당자 확인";
            trs_Save.KeyName = "toinb_dataid4";
            // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
            // const sbmParams = {
            //     YYYY : scwin.periodYYYY,
            //     VALU_TM_TP_CD : scwin.periodTmCd,
            //     USERID : scwin.pEmpId,
            //     MKTCD : scwin.pMktCd
            // };
            const sbmOptions = {
                id : "sbm_trs_Save",
                action : "/RepMajagnt.do",
                ref : "dts_Period",
                target : "trs_Save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};
